#[cfg(test)]
mod tests {
    /// Strictly ascending: binary search demands it, and it doubles as
    /// a dedup check.
    #[test]
    fn table_is_sorted_by_spell_id() {
        assert!(super::TABLE.windows(2).all(|w| w[0].0 < w[1].0));
    }

    /// The edition's specializations hold no spell of their own: no
    /// entry names one.
    #[test]
    fn no_entry_names_a_spec() {
        assert!(super::TABLE.iter().all(|e| e.2 == 0));
    }
}
